import { describe, it, expect } from "vitest";
import { createGeospatialCamera, setGeospatialOrientation } from "@babylonjs/lite";
import { tiltGlobeCamera } from "./globe-tilt.js";

describe("tiltGlobeCamera", () => {
    it("tilts a fresh camera at max zoom and keeps tilt through zoom", () => {
        const R = 6371000;
        const cam = createGeospatialCamera({ planetRadius: R });
        const r0 = cam.radius, yaw0 = cam.yaw, c0 = { ...cam.center };
        tiltGlobeCamera(cam, 0.8);
        expect(cam.pitch).toBeCloseTo(0.8, 9);
        expect(cam.radius).toBe(r0);
        expect(cam.yaw).toBe(yaw0);
        expect(cam.center).toEqual(c0);
        // lookAt is at the requested angle from straight down
        const up = { x: cam.center.x / R, y: cam.center.y / R, z: cam.center.z / R };
        const d = -(cam._lookAt.x * up.x + cam._lookAt.y * up.y + cam._lookAt.z * up.z);
        expect(Math.acos(d)).toBeCloseTo(0.8, 6);
        for (const r of [R * 3, R * 1.5, R * 0.5, 100]) {
            cam.radius = r;
            expect(cam.pitch).toBeCloseTo(0.8, 9);
        }
        setGeospatialOrientation(cam, { radius: r0 });
        expect(cam.pitch).toBeCloseTo(0.8, 9);
    });
});
EOF
